import {importedInfo,importedGloss} from './imported-vocabulary.js';
import {reviewGrades,scheduleReview} from './review-schedule.js';
import {accountButton,showAccount} from './account-ui.js';
import {readState,writeState} from './account-store.js';
import {vocabularyInfo} from './ielts-vocabulary.js';
import {grammarPage,initGrammar} from './grammar.js';
import {ieltsPage,initIelts} from './ielts.js';
import {words,wordMap,courses,courseMap} from './data.js';
import {answerReview,reviewAudio,markReviewPlayed,useReviewText,excludeKnownWord,restoreKnownWord,initial,localDay,addDays,dayLog,dueSenses,remainingWords,plannedCount,projectedFinish,dailyStats,begin,answerBare,answerSense,correctAnswer,continueLearning,leaveRest,activeExample,completedWords,validateState} from './engine.js';
import {createArticle,makeQuiz} from './content.js';
const KEY='lexiday.v1';let storageError=false,state;
try{const raw=readState(KEY);state=raw?validateState(JSON.parse(raw)):initial();}catch{state=initial();storageError=true;}
let route=location.hash.slice(1)||'ielts',courseFilter='全部',translation=false,highlight=true,selectedWord=null,toastTimer,restTimer;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={today:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',courses:'<path d="M3 4h7a2 2 0 0 1 2 2v15a3 3 0 0 0-3-2H3zM21 4h-7a2 2 0 0 0-2 2v15a3 3 0 0 1 3-2h6z"/>',reading:'<path d="M5 3h14v18H5zM8 7h8M8 11h8M8 15h5"/>',quiz:'<path d="M3 14v-2a9 9 0 0 1 18 0v2M3 13h4v7H3zM17 13h4v7h-4z"/>',report:'<path d="M4 20h17M7 16v-5M12 16V4M17 16V8"/>',sound:'<path d="m11 5-6 4H2v6h3l6 4zM15 8a6 6 0 0 1 0 8M18 5a10 10 0 0 1 0 14"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',settings:'<path d="M4 7h16M4 17h16M8 4v6M16 14v6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>'};
const icon=(id,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[id]||icons.courses}</svg>`;
function save(){if(storageError)return;try{writeState(KEY,JSON.stringify(state));}catch{storageError=true;toast('浏览器无法保存进度，请导出备份，避免关闭页面后丢失。');}}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',4500);}
function today(){return localDay();}function log(){return dayLog(state,today());}
function nav(to){route=to;location.hash=to;render();document.querySelector('main')?.focus();window.scrollTo({top:0,behavior:'instant'});}
window.addEventListener('hashchange',()=>{if(location.hash==='#main'){document.getElementById('main')?.focus();return;}route=location.hash.slice(1)||'ielts';render();});
function header(){const selected=route.startsWith('ielts')?'ielts':route==='learn'?'today':route;return `<header class="topbar"><a class="brand" href="#ielts"><span class="logo">L</span>词序 <small>Lexiday</small></a><nav aria-label="主导航">${[['ielts','雅思计划'],['grammar','语法课堂'],['today','单词学习'],['courses','词书课程'],['reading','今日阅读'],['quiz','听力测验'],['report','学习报告']].map(([id,label])=>`<a href="#${id}" ${selected===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span></a>`).join('')}</nav>${accountButton()}</header>`;}
function pageTitle(eyebrow,title,sub,action=''){return `<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="muted">${sub}</p></div>${action}</div>`;}
function progressBar(value,total){return `<div class="progress"><span style="width:${Math.min(100,total?value/total*100:0)}%"></span></div>`;}
const completedIn=c=>c.words.filter(id=>state.knownWords?.[id]||wordMap[id].senses.every(s=>state.records[s.id]?.level&&!state.records[s.id]?.pending)).length;
function todayPage(){const c=courseMap[state.course],stats=dailyStats(state),l=log(),count=plannedCount(state),q=state.session;const active=q?.day===today()&&q.stage!=='done';const allDone=q?.day===today()&&q.stage==='done';const left=remainingWords(state).length,days=Math.ceil(left/count);const current=active?courseMap[q.course]:c;
 return `${pageTitle('A LITTLE, EVERY DAY','今天，也向前一点。','让每个单词，从眼熟变成真正理解。',`<span class="date-label">${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</span>`)}<div class="dashboard"><div class="main-column"><section class="focus"><div><div class="focus-meta"><span class="pill">${active?'继续上次进度':'当前词书'}</span><span>${current.id.startsWith('ielts-')?'雅思 GT 精选词库':'示例词库'}</span></div><h2>${current.name}</h2><p>${active?'你的学习进度已经保存，接着上一次继续。':'优先完成到期听音复习，再学习新词。'}</p><div class="focus-progress"><span>词书进度 ${completedIn(current)} / ${current.words.length}</span>${progressBar(completedIn(current),current.words.length)}</div><button class="primary" data-action="start" ${state.plan.paused?'disabled':''}>${state.plan.paused?'计划已暂停':active?'继续学习':allDone&&stats.new>=count?'查看今日成果':'开始今日学习'} ${icon('arrow')}</button></div><div class="daily-target"><div class="ring" style="--p:${Math.min(100,stats.new/count*100)}%"><div><b>${String(Math.max(0,count-stats.new)).padStart(2,'0')}</b><span>待学新词</span></div></div><span>每日计划 ${count} 词</span></div></section><div class="stats-grid"><div class="stat"><span>${icon('courses')}今日新学</span><b>${stats.new}<small> / ${count} 词</small></b><p>按单词去重统计</p></div><div class="stat"><span>${icon('clock')}到期复习</span><b>${stats.due}<small> 个词义</small></b><p>先听音回想，再逐级提示</p></div><div class="stat"><span>${icon('check')}今日通过</span><b>${completedWords(state).length}<small> 词</small></b><p>已完成规定词义</p></div></div><section class="panel journey-panel"><div class="section-heading"><h2>今天的学习路径</h2><span class="muted">一步一步，记得更牢</span></div><div class="journey">${[['01','单词与语境','自测 · 详解 · 强化','today'],['02','读一篇短文','把今天的词串起来','reading'],['03','听力小测验','在声音中辨认词义','quiz']].map(([num,title,desc,id])=>`<button data-action="${id==='today'?'start':'navigate'}" data-to="${id}" class="journey-step"><span class="step-number">${num}</span><strong>${title}</strong><small>${desc}</small>${icon('arrow')}</button>`).join('')}</div></section><section class="panel group-preview"><div class="section-heading"><h2>有关联，也有区别</h2><span class="pill">对比记忆</span></div><div class="word-pair"><span>hinder<small>v. 阻碍</small></span><i>≠</i><span>hinge<small>n. 铰链</small></span></div><p class="muted">长得像，不一定意思相近。详解页会帮你看清每一处不同。</p></section></div><aside class="side-column"><section class="panel plan-card"><div class="section-heading"><h2>我的计划</h2><button class="icon-btn" data-action="plan" aria-label="调整学习计划">${icon('settings')}</button></div><div class="plan-count"><b>${count}</b><span>新词 / 天</span></div><div class="info-row"><span>当前词库</span><strong>${c.words.length} 词</strong></div><div class="info-row"><span>剩余新词</span><strong>${left} 词</strong></div><div class="info-row"><span>预计完成</span><strong>${left?projectedFinish(state):'已学完'}</strong></div><button class="full-width" data-action="plan">调整学习计划</button><button class="text-button full-width" data-action="pause">${state.plan.paused?'恢复学习计划':'暂停计划'}</button><p class="fine">${state.plan.paused?'计划已暂停，学习记录会保留。':'完成日期仅指新词学完，后续仍需复习。'}</p></section><section class="tip-card"><span class="mini-label">记忆小约定</span><h3>不认识，也没关系。</h3><p>一个词义选过“不认识”，就在不同轮次认识它 3 次。慢一点，记得久一点。</p><div class="three-dots"><span>1</span><i></i><span>2</span><i></i><span>3</span>${icon('check')}</div></section><p class="fine demo-note">演示模式 · 访客本机保存 · 登录后云端同步<br>自主整理 · 非官方完整词表</p></aside></div>`;
}
function coursesPage(){const items=courses.filter(c=>courseFilter==='全部'||c.level===courseFilter);return `${pageTitle('YOUR WORD LIBRARY','选一本，开始积累。','15 个学习方向，按你的阶段一步步来。')}<section class="panel vocabulary-banner"><span class="pill">词库更新 · ${vocabularyInfo.version}</span><h2>雅思基础：精选语境词 + 上传扩展词表</h2><p>导入 ${importedInfo.entries} 个去重词条，新增 ${importedInfo.added} 词，与原词库共享 ${importedInfo.overlap} 词。原有 220 词保留例句与学习记录。</p><p class="fine">${importedInfo.source}。新增词条缺少例句与英文解释时使用词条自测，跳过缺失提示；不伪造语境或关联。</p><p class="fine">${vocabularyInfo.description} 分数还取决于搭配、语法、理解和表达能力。</p><div class="actions">${vocabularyInfo.sources.map(s=>`<a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title} ↗</a>`).join('')}</div></section><div class="toolbar"><div class="segmented" role="group" aria-label="课程级别">${['全部','基础','进阶','拓展'].map(f=>`<button data-action="filter" data-filter="${f}" class="${courseFilter===f?'active':''}">${f}</button>`).join('')}</div><span class="muted">${courses.filter(c=>c.words.length).length} 本可学习 · ${words.length} 个去重单词</span></div><div class="course-grid">${items.map((c)=>`<article class="course-card ${c.words.length?'':'unavailable'}"><div class="course-cover ${c.color}"><span>${c.label}</span><div>${c.name}</div><small>${c.level} / ${c.id.startsWith('ielts-')?'GT 精选版':c.words.length?'示例版':'筹备中'}</small></div><div class="course-body"><h2>${c.name}</h2><p>${c.audience}</p><div class="info-row"><span>${c.words.length} 个单词</span><span>${c.words.length?completedIn(c)+' / '+c.words.length+' 已学 / 熟知':'词库待补充'}</span></div>${progressBar(completedIn(c),c.words.length)}${c.words.length?`<button class="text-button full-width" data-action="vocabulary" data-id="${c.id}">查看词表与释义</button>`:""}<button class="full-width ${state.course===c.id?'primary':''}" data-action="course" data-id="${c.id}" ${!c.words.length?'disabled':''}>${!c.words.length?'暂未开放':state.course===c.id?'当前词书':'选择词书'}</button></div></article>`).join('')}</div><p class="fine">跨课程共享相同词义的学习记录。示例内容为原创教学材料，不代表官方收词范围。</p>`;}
function highlightWord(en,id,interactive=false,senseId=''){const re=new RegExp(`\\b(${id})\\b`,'gi');return esc(en).replace(re,interactive?`<button class="inline-word" data-action="gloss" data-id="${id}" data-sense="${senseId}">$1</button>`:'<mark>$1</mark>');}
function speakButton(text,label='播放发音',cls=''){return `<button class="sound-btn ${cls}" data-action="speak" data-text="${esc(text)}" aria-label="${label}">${icon('sound')}<span>${label}</span></button>`;}
function learnPage(){const q=state.session;if(!q||q.day!==today())return empty('今天的单词，准备好了。','开始后会先安排到期复习，再学习当前词书中的新词。','开始学习','start');if(q.stage==='done')return `<section class="completion panel"><div class="success-icon">${icon('check')}</div><div class="eyebrow">SESSION COMPLETE</div><h1>今天的词，离你更近了。</h1><p class="muted">已完成本轮卡片，接下来在文章和声音里再次遇见它们。</p><div class="completion-stats"><span><b>${log().newWords.length}</b>新学单词</span><span><b>${log().reviewWords.length}</b>复习单词</span><span><b>${log().passed.length}</b>通过词义</span></div><div class="actions"><button class="primary" data-action="navigate" data-to="reading">阅读今日文章 ${icon('arrow')}</button><button data-action="navigate" data-to="quiz">开始听力测验</button></div><p class="fine">当天通过 ≠ 永久记住。未记住的词最迟明天复习；后续根据听音、语境或文字提示程度调整间隔。</p></section>`;
 const t=q.current,w=wordMap[t.wordId],se=w.senses.find(s=>s.id===t.senseId),st=q.states[se.id],realEx=activeExample(state),ex=realEx||{en:'',zh:'原词表未提供例句，本次仅进行词条释义自测。'};const total=Object.keys(q.states).length,passed=Object.values(q.states).filter(s=>s.passed).length;
 const top=`<div class="learning-top"><a href="#today">‹ 返回今日学习</a><span>${courseMap[q.course].name} · ${q.types[w.id]==='review'?'到期复习':'新词学习'}</span><span>${passed} / ${total} 词义通过</span></div>${progressBar(passed,total)}<div class="learning-layout"><div class="learning-main">${q.types[w.id]==='review'?'<div class="learning-steps"><span>听读音</span><i></i><span>听语境</span><i></i><span>看拼写</span><i></i><span>看例句</span></div>':`<div class="learning-steps"><span class="${q.stage==='bare'?'current':''}">01 裸词自测</span><i></i><span class="${q.stage==='sentence'?'current':''}">02 ${realEx?'例句':'词条'}自测</span><i></i><span class="${q.stage==='detail'?'current':''}">03 单词详解</span></div>`}`;
 const side=q.types[w.id]==='review'?`</div><aside class="learning-side"><section class="panel"><h3>提示越少，间隔越长</h3><p>听音认识权重 1；听语境 0.75；看拼写 0.5；看例句 0.25；仍不认识 0。</p><p class="fine">本次评级在核对释义后提交。仍不认识最迟明天再来，不会因今天反复点击而延长间隔。</p><button data-action="known-list">管理已熟知词</button></section></aside></div>`:`</div><aside class="learning-side"><div class="panel"><span class="mini-label">${st.strong?'强化记忆':'词义自测'}</span><h3>${st.strong?'再认识它几次。':'认真想一想，再选择。'}</h3>${st.strong?`<div class="recognition-dots">${[1,2,3].map(i=>`<span class="${st.known>=i?'filled':''}">${st.known>=i?'✓':i}</span>`).join('')}</div><p>当前词义 ${st.known} / 3 次有效认识。中途再选不认识，次数不清零。</p>`:'<p>根据自己能否理解来判断。看过详解，不等于已经记住。</p>'}<span class="pill">第 ${t.round} 次语境测试</span></div><div class="aside-note">${icon('clock')}<p>进度自动保存。可以随时退出，下次接着学。</p></div></aside></div>`;
 let body='';
 if(q.stage==='review')return top+reviewCard(q,w,se,realEx)+side;
 if(q.stage==='rest'){const sec=Math.max(0,Math.ceil((q.readyAt-Date.now())/1000));body=`<section class="panel recall-card"><span class="pill">收尾复习</span><h2>稍停一下，再回想。</h2><p class="muted">目前只剩下同一个单词。先移开视线，尝试回想词义，再进入下一轮。</p><button class="primary" data-action="rest" id="rest-button" ${sec?'disabled':''}>${sec?`稍后继续 · ${sec} 秒`:'进入下一轮'}</button></section>`;clearInterval(restTimer);restTimer=setInterval(()=>{const b=document.getElementById('rest-button');if(!b){clearInterval(restTimer);return;}const s=Math.max(0,Math.ceil((q.readyAt-Date.now())/1000));b.disabled=!!s;b.textContent=s?`稍后继续 · ${s} 秒`:'进入下一轮';if(!s)clearInterval(restTimer);},300);}
 if(q.stage==='bare')body=`<section class="panel recall-card"><span class="pill">先凭印象，不看释义</span><div class="bare-word">${w.word}</div><div class="phonetic">${w.ipa} ${speakButton(w.word,'听发音','compact')}</div><p class="question-prompt">你认识这个单词吗？</p><div class="answer-buttons"><button data-action="bare-no"><span>还不认识</span><small>没关系，接下来一起学</small></button><button class="primary" data-action="bare-yes"><span>认识</span><small>去例句中确认一下</small></button></div></section>`;
 if(q.stage==='sentence')body=`<section class="panel recall-card"><span class="pill">${q.bareDone[w.id]&&t.round===1?'再判断一次':'在新语境中回想'}</span><div class="sentence-word">${w.word} <span>${se.ipa||w.ipa}</span></div>${realEx?`<p class="example-sentence">${highlightWord(ex.en,w.id)}</p>${speakButton(ex.en,'播放例句')}`:'<p class="warning">上传词表暂缺例句，改为词条释义自测，不计作语境测试。</p>'}<p class="question-prompt">${realEx?'你知道它在这句话里的意思吗？':'你能说出这个词条的主要含义吗？'}</p><div class="answer-buttons"><button data-action="sense-no"><span>不认识</span><small>查看释义，加入强化</small></button><button class="primary" data-action="sense-yes"><span>认识</span><small>查看详解，核对理解</small></button></div></section>`;
 if(q.stage==='detail')body=`<section class="panel detail-card"><div class="detail-heading"><div><span class="eyebrow">WORD IN CONTEXT</span><h1>${w.word}</h1><span class="muted">${se.ipa||w.ipa}</span></div>${speakButton(w.word,'听发音','compact')}</div><div class="tested-meaning"><div class="section-heading"><span class="mini-label">${realEx?'本次核对的词义':'上传词表释义（尚未细分词义）'}</span><span class="answer-tag ${q.lastAnswer?'yes':'no'}">${q.lastAnswer?'你选择了认识':q.types[w.id]==='review'?'明天再复习':'已加入强化'}</span></div><h2><span class="pos">${se.pos}</span>${esc(se.meaning)}</h2><p class="detail-example">${highlightWord(ex.en,w.id)}</p><p class="muted">${esc(ex.zh)}</p>${realEx?speakButton(ex.en,'播放例句'):''} ${q.lastAnswer?'<button class="text-button" data-action="correct">刚才点错了，其实不认识</button>':''}</div><div class="section-heading"><h2>词性与常用词义</h2><span class="fine">当前课程范围</span></div>${w.senses.map(s=>`<div class="meaning-row"><div><span class="pos">${s.pos}</span><strong>${esc(s.meaning)}</strong>${s.id===se.id?'<span class="pill">本次测试</span>':q.states[s.id]?.passed?'<span class="pill">当天通过</span>':'<span class="muted meaning-status">'+(q.states[s.id]?'后续单独测试':'已学词义')+'</span>'}</div><p>${s.examples[0]?highlightWord(s.examples[0].en,w.id):'例句待补充'}</p><p class="muted">${esc(s.examples[0]?.zh||'')}</p></div>`).join('')}<section class="word-notes"><div class="section-heading"><h2>单词笔记</h2><span class="pill">看清区别，减少混淆</span></div>${!w.notes.length?'<p class="muted">暂未收录可靠的关联词笔记，可先通过上方例句掌握用法。</p>':''}${relationCards(w)}<p class="fine">关联词仅辅助理解，不会自动加入今日任务。</p></section>${q.reviewGrade!=null?`<p class="review-result">${reviewGrades[q.reviewGrade].label} · 权重 ${reviewGrades[q.reviewGrade].weight} · 下次复习：${addDays(q.day,scheduleReview(state.records[se.id],q.reviewGrade).interval)}</p>`:''}<div class="detail-footer"><p class="fine">阅读详解和点击继续，不增加“认识”次数。</p><button class="primary" data-action="continue">继续学习 ${icon('arrow')}</button></div></section>`;
 return top+body+`<button class="text-button" data-action="exclude-known" data-id="${esc(w.id)}">这个词我早已熟知，不再安排学习与复习</button>`+side;
}
function empty(title,sub,label,action,to=''){return `<section class="panel empty-state"><div class="empty-icon">${icon(route==='reading'?'reading':route==='quiz'?'quiz':'courses')}</div><h1>${title}</h1><p class="muted">${sub}</p><button class="primary" data-action="${action}" data-to="${to}">${label} ${icon('arrow')}</button></section>`;}
function readyForExtras(){return log().touched.length&&state.session?.day===today()&&state.session.stage==='done';}
function readingPage(){if(!readyForExtras())return empty('先积累，再读懂一段故事。','完成今日卡片任务后，这里会出现包含今日单词的英文短文。','去完成今日学习','start');const a=log().article;if(!a)return `${pageTitle('WORDS BECOME A STORY','把今天的词，放进故事里。','离线模式：原示例短文或雅思语境例句合集，未调用 AI。')}<section class="panel empty-state">${icon('reading','large-icon')}<h2>${log().touched.length} 个单词，一次语境回顾。</h2><p class="muted">列出今日词汇的可用语境材料与覆盖率；缺少例句的词明确列为未覆盖。</p><button class="primary" data-action="article">生成今日阅读 ${icon('arrow')}</button></section>`;
 const chosen=selectedWord&&a.paragraphs.find(p=>p.wordId===selectedWord.wordId&&p.senseId===selectedWord.senseId);const se=chosen&&wordMap[chosen.wordId].senses.find(s=>s.id===chosen.senseId);
 return `${pageTitle('DAILY READING','今天的词，今天的故事。','在完整句子中，再次遇见你学过的词。')}<div class="reading-layout"><article class="panel article"><div class="article-tools"><span class="pill">${a.collection?'语境例句合集 · 非连贯文章':'演示短文 · 预编内容组合'}</span><div><button data-action="toggle-highlight" aria-pressed="${highlight}">高亮${highlight?'开':'关'}</button><button data-action="translation" aria-pressed="${translation}">${translation?'隐藏':'显示'}译文</button></div></div><div class="eyebrow">THE DAILY NOTEBOOK</div><h1>${a.title}</h1><p class="muted">${a.subtitle}</p><div class="reading-meta"><span>${a.covered}/${a.total} 单词有语境材料</span>${speakButton([a.intro,...a.paragraphs.map(p=>p.en),a.ending].join(' '),'全文朗读')}<button class="text-button" data-action="stop-speech">停止</button></div>${a.missing?.length?`<p class="warning">以下词条暂缺例句，未计入语境覆盖：${a.missing.map(esc).join('、')}。请在词表中复习释义。</p>`:''}<div class="article-body ${highlight?'':'no-highlight'}"><p>${a.intro}</p>${translation?`<p class="translation">${a.introZh}</p>`:''}${a.paragraphs.map((p,i)=>`${i%5===0&&a.paragraphs.length>10?`<span class="part-label">片段 ${Math.floor(i/5)+1}</span>`:''}<p>${highlightWord(p.en,p.wordId,true,p.senseId)}</p>${translation?`<p class="translation">${p.zh}</p>`:''}`).join('')}<p>${a.ending}</p>${translation?`<p class="translation">${a.endingZh}</p>`:''}</div><div class="detail-footer"><p class="fine">覆盖单词，不代表覆盖这个单词的全部词义。</p><button class="primary" data-action="navigate" data-to="quiz">进入听力测验 ${icon('arrow')}</button></div></article><aside><section class="panel glossary"><h2>${se?esc(chosen.wordId):'阅读词卡'}</h2>${se?`<span class="pos">${se.pos}</span><h3>${esc(se.meaning)}</h3><p>${esc(chosen.en)}</p><p class="muted">${esc(chosen.zh)}</p>${speakButton(chosen.wordId,'听发音')}`:'<p class="muted">点击文章中的目标词，在这里查看当前语境中的释义。</p>'}</section><section class="panel coverage-panel"><h3>今日单词清单</h3><div class="word-chips">${a.paragraphs.map(p=>`<button data-action="gloss" data-id="${p.wordId}" data-sense="${p.senseId}">${p.wordId} <span>✓</span></button>`).join('')}</div><p class="fine">语境覆盖 · ${a.covered}/${a.total}${a.missing?.length?`；${a.missing.length} 词暂缺例句，未计入覆盖。`:''}</p></section></aside></div>`;
}
function quizPage(){if(!readyForExtras())return empty('用耳朵，再认识一次。','先完成今日卡片学习，再用听力检验词义理解。','去完成今日学习','start');const quiz=log().quiz;if(!quiz)return empty('准备好，听一听。','每次最多 10 题，优先测试薄弱词义。使用设备英文语音，不需要 API。','开始听力测验','quiz-start');
 if(quiz.index>=quiz.questions.length){const correct=quiz.answers.filter(a=>a.correct).length,assisted=quiz.answers.filter(a=>a.assisted).length;return `<section class="panel completion"><div class="success-icon">${icon('quiz')}</div><div class="eyebrow">LISTENING COMPLETE</div><h1>每次听懂，都是进步。</h1><div class="score">${Math.round(correct/quiz.questions.length*100)}<small>%</small></div><p class="muted">答对 ${correct} / ${quiz.questions.length} 题 · 原文辅助 ${assisted} 题</p><div class="actions"><button class="primary" data-action="navigate" data-to="report">查看学习报告</button>${correct<quiz.questions.length?'<button data-action="quiz-wrong">当天错题加练</button>':''}</div><div class="quiz-review">${quiz.answers.map((a,i)=>`<div class="review-row"><span class="${a.correct?'correct-text':'wrong-text'}">${a.correct?'✓':'×'}</span><strong>${quiz.questions[i].wordId}</strong><span>${quiz.questions[i].meaning}</span><small>${a.assisted?'使用原文辅助':''}</small></div>`).join('')}</div><p class="fine">错题词义已安排明日复习。当天通过的词不会自动重新刷卡。</p></section>`;}
 const question=quiz.questions[quiz.index],answer=quiz.answers[quiz.index];return `${pageTitle('LISTEN & UNDERSTAND','听懂句子里的那个词。','根据语境，选择它在这句话中的意思。')}<div class="quiz-container"><div class="quiz-heading"><span>第 ${quiz.index+1} / ${quiz.questions.length} 题</span><span class="pill">设备语音 · 演示题库</span></div>${progressBar(quiz.index,quiz.questions.length)}<section class="panel quiz-card"><button class="listen-orb" data-action="quiz-play" aria-label="播放测验句子">${icon('sound')}</button><p class="muted">${quiz.played?'可以再次点击重播':'先点击上方按钮听句子'}</p><h2>“${question.wordId}” 在句中是什么意思？</h2><button class="text-button" data-action="reveal" ${quiz.revealed||quiz.submitted?'disabled':''}>${quiz.revealed?'已使用原文辅助':'显示原文（记录为辅助作答）'}</button>${quiz.revealed||quiz.submitted?`<p class="quiz-transcript">${highlightWord(question.en,question.wordId)}</p>`:''}<div class="options">${question.options.map((option,i)=>`<button data-action="option" data-index="${i}" ${quiz.submitted||(!quiz.played&&!quiz.revealed)?'disabled':''} class="${quiz.submitted?(option===question.meaning?'correct':answer.chosen===option?'incorrect':''):''}"><span>${'ABCD'[i]}</span>${option}${quiz.submitted&&option===question.meaning?icon('check'):''}</button>`).join('')}</div>${quiz.submitted?`<div class="answer-explanation"><strong class="${answer.correct?'correct-text':'wrong-text'}">${answer.correct?'回答正确':'这次再巩固一下'}</strong><p>${question.zh}</p><p><span class="pos">${question.pos}</span>本句中的 <strong>${question.wordId}</strong> 表示「${question.meaning}」。其他选项不符合本句语境。</p><button class="primary" data-action="quiz-next">${quiz.index===quiz.questions.length-1?'查看测验结果':'下一题'} ${icon('arrow')}</button></div>`:''}</section></div>`;
}
function reportPage(){const l=log(),quiz=l.quiz,allAnswers=[...(l.quizHistory||[]).flatMap(q=>q.answers),...(quiz?.answers||[])],answered=allAnswers.length,correct=allAnswers.filter(a=>a.correct).length;const weak=Object.entries(state.records).filter(([,r])=>r.weak).sort((a,b)=>a[1].due.localeCompare(b[1].due));const last7=Array.from({length:7},(_,i)=>addDays(today(),i-6));const max=Math.max(5,...last7.map(d=>state.days[d]?.passed.length||0));return `${pageTitle('YOUR LEARNING, IN FOCUS','一点一滴，都算数。','当天通过是一个起点，长期掌握来自持续复习。')}<div class="report-stats">${[[l.newWords.length,'今日新学 / 词'],[l.reviewWords.length,'今日复习 / 词'],[answered?Math.round(correct/answered*100)+'%':'—','测验正确率'],[allAnswers.filter(a=>a.assisted).length,'原文辅助 / 题']].map(([v,label])=>`<div class="stat"><b>${v}</b><span>${label}</span></div>`).join('')}</div><div class="report-layout"><section class="panel"><div class="section-heading"><h2>最近 7 天</h2><span class="muted">通过词义数</span></div><div class="bar-chart" role="img" aria-label="最近七天通过词义数量">${last7.map(d=>{const value=state.days[d]?.passed.length||0;return `<div class="bar-column"><span>${value}</span><div class="bar-track"><div style="height:${value/max*100}%" class="${d===today()?'current':''}"></div></div><small>${d.slice(5).replace('-','/')}</small></div>`;}).join('')}</div></section><section class="panel"><h2>记忆进展</h2><button data-action="known-list">管理已熟知词（${Object.keys(state.knownWords||{}).length}）</button><div class="info-row"><span>今天通过的词义</span><strong>${l.passed.length}</strong></div><div class="info-row"><span>累计学过的词义</span><strong>${Object.keys(state.records).length}</strong></div><div class="info-row"><span>达到第 6 学习阶段</span><strong>${Object.values(state.records).filter(r=>r.level===6).length}</strong></div><p class="fine">只听读音认识：上次间隔 ×2.5；听语境认识：×1.6；看拼写认识：×0.8（2–7 天）；看例句认识：×0.5（1–3 天）；仍不认识：1 天。自测权重是本站启发式设计，并非精确预测记忆。</p></section></div><section class="panel"><div class="section-heading"><h2>还需要多见几次</h2><span class="pill">薄弱词义 ${weak.length}</span></div>${weak.length?`<div class="table-wrap"><table><thead><tr><th>单词</th><th>需要巩固的词义</th><th>下次复习</th><th>进度</th></tr></thead><tbody>${weak.map(([id,r])=>{const s=wordMap[r.wordId].senses.find(s=>s.id===id);return `<tr><td><strong>${r.wordId}</strong></td><td>${s.pos} ${esc(s.meaning)}</td><td>${r.due<=today()?'已到期':r.due}</td><td>第 ${r.level} 阶段</td></tr>`;}).join('')}</tbody></table></div>`:'<p class="muted">暂无薄弱词义。学习中选择“不认识”或测验答错后，会在这里记录。</p>'}</section><div class="report-actions"><button data-action="settings">备份学习数据</button><button class="primary" data-action="navigate" data-to="today">返回今日学习 ${icon('arrow')}</button></div>`;}
function render(){clearInterval(restTimer);if(!['grammar','ielts','ielts-plan','ielts-listening','ielts-writing','ielts-speaking','ielts-reading','ielts-notebook','ielts-review','today','courses','learn','reading','quiz','report'].includes(route))route='ielts';const pages={today:todayPage,courses:coursesPage,learn:learnPage,reading:readingPage,quiz:quizPage,report:reportPage};document.getElementById('app').innerHTML=header()+`<main class="main ${route==='learn'?'study-main':''}" id="main" tabindex="-1">${storageError?'<div class="warning">本地存储不可用或旧数据无法读取。请在设置中导出当前进度；原有数据尚未自动清除。</div>':''}${route==='grammar'?grammarPage():route.startsWith('ielts')?ieltsPage(route):pages[route]()}</main><footer class="site-footer"><span>词序 Lexiday</span><span>自主整理词库 · 支持账号同步</span><button class="text-button" data-action="settings">数据与说明</button></footer>`;document.title=({grammar:'语法课堂',today:'今日学习',courses:'词书课程',learn:'单词学习',reading:'今日阅读',quiz:'听力测验',report:'学习报告'}[route]||'雅思半年计划')+' · 词序 Lexiday';}
function dialog(content){document.querySelector('dialog')?.remove();const d=document.createElement('dialog');d.innerHTML=`<div class="dialog-heading"><h2>${content.title}</h2><button class="icon-btn" data-action="close-dialog" aria-label="关闭">${icon('close')}</button></div>${content.body}`;document.body.append(d);d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});d.showModal();}
let vocabularyId='',vocabularyPage=0,vocabularyQuery='',vocabularyType='全部';
function showVocabulary(id){vocabularyId=id;vocabularyPage=0;vocabularyQuery='';vocabularyType='全部';const c=courseMap[id];if(!c)return;dialog({title:c.name+' · 词表',body:`<p>${c.words.length} 个词条。词族关联不等于同义关系；形近词按拼写识别。</p><label for="vocabulary-search">搜索英文、中文或主题</label><input id="vocabulary-search" type="search" autocomplete="off"><label for="vocabulary-type">关联分类</label><select id="vocabulary-type"><option>全部</option><option>近义词</option><option>形近词</option><option>同词族</option></select><div id="vocabulary-items"></div>`});renderVocabulary();}
function renderVocabulary(){const c=courseMap[vocabularyId];if(!c)return;const list=c.words.filter(id=>{const w=wordMap[id];return [w.word,w.topic||w.group,...w.senses.map(s=>s.meaning),...(importedGloss[id]||[])].join(' ').toLowerCase().includes(vocabularyQuery)&&(vocabularyType==='全部'||w.notes.some(n=>n.type===vocabularyType||vocabularyType==='同词族'&&n.type==='词族'));});const total=Math.max(1,Math.ceil(list.length/40));vocabularyPage=Math.max(0,Math.min(vocabularyPage,total-1));document.getElementById('vocabulary-items').innerHTML=`<p class="fine">匹配 ${list.length} 词 · 第 ${vocabularyPage+1} / ${total} 页</p><div class="vocabulary-list">${list.slice(vocabularyPage*40,vocabularyPage*40+40).map(id=>{const w=wordMap[id];return `<details class="vocabulary-entry"><summary><strong>${esc(w.word)}</strong> <span class="muted">${esc(w.ipa)}</span><small>${esc(w.senses[0].meaning)}</small></summary>${speakButton(w.word,'听发音')}${w.imported?'<p class="warning">上传词表释义待审校；暂缺例句和英文解释，采用词条级自测。</p>':''}${w.senses.map(se=>`<div class="meaning-row"><strong>${esc(se.pos)} ${esc(se.meaning)}</strong>${se.definition?`<p>${esc(se.definition)}</p>`:''}${se.examples.map(ex=>`<p>${esc(ex.en)}</p><p class="muted">${esc(ex.zh)}</p>`).join('')}</div>`).join('')}${!w.imported&&importedGloss[id]?`<p class="fine">上传词表补充参考（未自动拆分为新测试词义）：${esc(importedGloss[id].join('；'))}</p>`:''}${relationCards({...w,notes:w.notes.filter(n=>vocabularyType==='全部'||n.type===vocabularyType||vocabularyType==='同词族'&&n.type==='词族')})}<button data-action="${state.knownWords?.[id]?'restore-known':'exclude-known'}" data-id="${esc(id)}">${state.knownWords?.[id]?'恢复复习':'已熟知，不再安排学习与复习'}</button></details>`;}).join('')}</div><div class="vocabulary-pagination"><button data-action="vocab-prev" ${vocabularyPage?'':'disabled'}>上一页</button><button data-action="vocab-next" ${vocabularyPage+1<total?'':'disabled'}>下一页</button></div>`;}
document.addEventListener('input',e=>{if(e.target.id==='vocabulary-search'){vocabularyQuery=e.target.value.trim().toLowerCase();vocabularyPage=0;renderVocabulary();}});
document.addEventListener('change',e=>{if(e.target.id==='vocabulary-type'){vocabularyType=e.target.value;vocabularyPage=0;renderVocabulary();}});
function showPlan(){dialog({title:'把学习安排得刚刚好',body:`<p class="muted">${courseMap[state.course].name} · 剩余 ${remainingWords(state).length} 个新词</p><form id="plan-form"><label for="plan-order">新词关联顺序</label><select id="plan-order" name="order">${[["source","原词表 / 主题顺序"],["meaning","近义词关联"],["spelling","形近词对比"],["family","同词族关联"]].map(([v,t])=>`<option value="${v}" ${(state.plan.order||"source")===v?"selected":""}>${t}</option>`).join("")}</select><p class="fine">有可靠关联时每组最多 5 词，不足不强行凑组。复习仍优先并打乱顺序。</p><label for="plan-mode">计划方式</label><select id="plan-mode" name="mode"><option value="count" ${state.plan.mode==='count'?'selected':''}>每天学习固定数量</option><option value="date" ${state.plan.mode==='date'?'selected':''}>按目标完成日期计算</option></select><div id="count-field" ${state.plan.mode==='date'?'hidden':''}><label for="plan-count">每天的新词数</label><input id="plan-count" name="count" type="number" min="1" max="100" required value="${state.plan.count}"></div><div id="date-field" ${state.plan.mode==='count'?'hidden':''}><label for="plan-target">目标完成日期</label><input id="plan-target" name="target" type="date" min="${today()}" value="${esc(state.plan.target||addDays(today(),6))}"></div><p class="fine">调整后会保留当前练习。新增任务将在本轮完成后按新的每日额度安排；复习数量另外计算。</p><button class="primary full-width" type="submit">保存计划</button></form>`});}
function settings(){dialog({title:'你的进度，由你保管',body:`<span class="pill">本机备份与账号同步</span><p>访客记录保存在当前浏览器。登录后，单词、语法与雅思进度自动同步到账号；可通过页面下方的账号入口查看同步状态。音频文件和临时录音不上传。</p><div class="settings-actions"><button data-action="export">导出学习备份</button><label class="file-label">导入并替换进度<input type="file" id="import-file" accept="application/json,.json"></label></div><p class="fine">导入前会要求确认。备份只含学习数据，不含密钥。</p><hr><h3>关于演示内容</h3><p class="muted">已提供 ${words.length} 个去重单词及 ${words.reduce((a,w)=>a+w.senses.length,0)} 个词义，覆盖零基础、中考、高考、雅思基础和雅思进阶五本课程。上传词表补充至雅思基础，缺少例句的词明确标注。词库不是官方完整词表，尚未经外部词典逐条认证。原有示例词使用预编短文；含新增雅思词时提供明确标注的独立语境例句合集。测验使用预编例句，未调用 AI。</p><p class="muted">朗读使用浏览器和设备提供的英文语音。无可用语音时可用原文辅助作答，并单独记录。</p>`});}
function speak(text,onEnd){if(!('speechSynthesis'in window)){toast('设备不支持朗读，可显示原文辅助学习。');return false;}window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.onend=()=>onEnd?.();u.lang='en-US';u.rate=.88;const voices=window.speechSynthesis.getVoices();const v=voices.find(v=>v.lang==='en-US')||voices.find(v=>v.lang.startsWith('en'));if(v)u.voice=v;u.onerror=e=>{if(!['canceled','interrupted'].includes(e.error))toast('语音暂时不可用，请检查设备语音或使用原文辅助。');};window.speechSynthesis.speak(u);return true;}
function start(){if(state.plan.paused){showPlan();toast('计划已暂停，请在首页恢复后开始。');return;}begin(state);save();nav('learn');}
function recordQuizOption(index){const q=log().quiz;if(!q||q.submitted||(!q.played&&!q.revealed))return;const question=q.questions[q.index];if(!Number.isInteger(index)||index<0||index>=question.options.length)throw new Error('选项无效。');const chosen=question.options[index],correct=chosen===question.meaning;q.answers.push({senseId:question.senseId,chosen,correct,assisted:q.revealed});q.submitted=true;if(!correct){const r=state.records[question.senseId];if(r&&!state.knownWords?.[r.wordId]){r.due=addDays(today(),1);r.weak=true;(state.unknownSenses??={})[question.senseId]=true;}}save();render();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action;if(['review-yes','review-no','review-text','continue','exclude-known'].includes(action))window.speechSynthesis?.cancel();try{if(['bare-yes','bare-no','sense-yes','sense-no','correct','continue','rest','review-play','review-yes','review-no','review-text'].includes(action)&&state.session?.day!==today()){begin(state);save();render();toast('新的一天，已重新安排今日任务。');return;}if(action==='navigate'){nav(b.dataset.to);return;}if(action==='start'){start();return;}if(action==='vocab-prev'||action==='vocab-next'){vocabularyPage+=action==='vocab-next'?1:-1;renderVocabulary();return;}if(action==='vocabulary'){showVocabulary(b.dataset.id);return;}if(action==='plan'){showPlan();return;}if(action==='settings'){settings();return;}if(action==='close-dialog'){b.closest('dialog')?.close();return;}if(action==='pause'){state.plan.paused=!state.plan.paused;save();render();toast(state.plan.paused?'计划已暂停，进度已保留。':'计划已恢复。');return;}if(action==='filter'){courseFilter=b.dataset.filter;render();return;}if(action==='course'){if(!courseMap[b.dataset.id]?.words.length)return;state.course=b.dataset.id;save();nav('today');toast('已切换词书，相同词义的进度已保留。');return;}if(action==='speak'){speak(b.dataset.text);return;}if(action==='stop-speech'){window.speechSynthesis?.cancel();return;}if(action==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='lexiday-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);return;}
 if(action==='review-play'){const snapshot=state.session;const cue=snapshot?.cue,task=snapshot?.current;if(speak(reviewAudio(state),()=>{if(state.session===snapshot&&snapshot.current===task&&snapshot.stage==='review'&&snapshot.cue===cue){markReviewPlayed(state);save();render();}}))toast('正在播放，听完后选择。');return;}else if(action==='review-text')useReviewText(state);else if(action==='review-yes'||action==='review-no')answerReview(state,action==='review-yes');else if(action==='exclude-known'){if(!confirm('标记为早已熟知后，此词全部词义将退出学习和复习队列。可在“已熟知词”中恢复。'))return;excludeKnownWord(state,b.dataset.id);document.querySelector('dialog')?.close();}else if(action==='restore-known'){restoreKnownWord(state,b.dataset.id);save();showKnownWords();render();return;}else if(action==='known-list'){showKnownWords();return;}else if(action.startsWith('bare-'))answerBare(state,action==='bare-yes');else if(action.startsWith('sense-'))answerSense(state,action==='sense-yes');else if(action==='correct'){correctAnswer(state);toast('已改为不认识，刚才这次认识不再计数。');}else if(action==='continue'){continueLearning(state);window.scrollTo({top:0,behavior:'instant'});}else if(action==='rest')leaveRest(state);else if(action==='article'){b.disabled=true;b.textContent='正在检查覆盖…';setTimeout(()=>{try{log().article=createArticle(log().touched,log().passed);save();render();}catch(err){render();toast(err.message);}},450);return;}else if(action==='translation'){translation=!translation;}else if(action==='toggle-highlight'){highlight=!highlight;}else if(action==='gloss'){selectedWord={wordId:b.dataset.id,senseId:b.dataset.sense};}else if(action==='quiz-start'||action==='quiz-wrong'){const nextQuiz=makeQuiz(state,log(),action==='quiz-wrong');if(log().quiz)(log().quizHistory??=[]).push(log().quiz);log().quiz=nextQuiz;}else if(action==='quiz-play'){const q=log().quiz;if(speak(q.questions[q.index].en))q.played=true;}else if(action==='reveal'){const q=log().quiz;if(!q.submitted)q.revealed=true;}else if(action==='option'){recordQuizOption(Number(b.dataset.index));return;}else if(action==='quiz-next'){const q=log().quiz;if(!q.submitted)return;window.speechSynthesis?.cancel();q.index++;q.submitted=false;q.revealed=false;q.played=false;}else return;save();render();if(['bare-yes','bare-no','sense-yes','sense-no','rest'].includes(action))window.scrollTo({top:0,behavior:'instant'});}catch(err){toast(err.message||'操作未完成，请重试。');}});
document.addEventListener('change',async e=>{if(e.target.id==='plan-mode'){document.getElementById('count-field').hidden=e.target.value!=='count';document.getElementById('date-field').hidden=e.target.value!=='date';}if(e.target.id==='import-file'){const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw new Error('文件过大，请选择有效学习备份。');const imported=validateState(JSON.parse(await f.text()));if(!confirm('导入将替换当前浏览器的全部学习进度，是否继续？'))return;state=imported;storageError=false;save();document.querySelector('dialog')?.close();render();toast('学习进度已恢复。');}catch(err){toast(err.message||'无法读取此备份。');}e.target.value='';}});
document.addEventListener('submit',e=>{if(e.target.id!=='plan-form')return;e.preventDefault();const f=new FormData(e.target);const count=Number(f.get('count')),mode=f.get('mode'),target=f.get('target');if(!Number.isInteger(count)||count<1||count>100){toast('每日数量需为 1–100 的整数。');return;}if(mode==='date'&&(!/^\d{4}-\d{2}-\d{2}$/.test(target)||target<today())){toast('请选择今天或之后的完成日期。');return;}state.plan={...state.plan,count,mode,target,order:f.get('order')||'source'};save();e.target.closest('dialog').close();render();toast('计划已保存，已有进度会保留。');});
initIelts({toast,render});
initGrammar({toast,render});
render();
// Optional WebMCP: all actions use the same state and UI functions as visitor controls.
const context=document.modelContext;const lifecycle=new AbortController();
if(context?.registerTool){const tools=[{name:'read_learning_progress',description:'Read the visitor’s current local learning progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({course:state.course,stats:dailyStats(state),stage:state.session?.stage||null})},{name:'configure_daily_word_count',description:'Set the daily new-word target from 1 to 100, preserving current progress.',inputSchema:{type:'object',properties:{count:{type:'integer',minimum:1,maximum:100}},required:['count'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({count})=>{if(!Number.isInteger(count)||count<1||count>100)throw new Error('count must be an integer from 1 to 100');state.plan={...state.plan,mode:'count',count};save();render();return {count};}},{name:'start_learning_session',description:'Start or resume the current learning session; does not answer or mark words as known.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:()=>{if(state.plan.paused)throw new Error('The plan is paused');start();return {stage:state.session.stage};}}];for(const t of tools)try{Promise.resolve(context.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

function reviewCard(q,w,se,ex){
 const titles={audio:'第一步 · 只听单词读音',context:'第二步 · 听例句与英文解释',spelling:'第三步 · 看单词拼写',sentence:'第四步 · 看英文例句'};
 const listening=['audio','context'].includes(q.cue);
 return `<section class="panel recall-card"><span class="pill">到期复习 · 逐级提示</span><h2>${titles[q.cue]}</h2>${listening?`<button class="primary review-speaker" data-action="review-play" aria-label="播放当前听力提示">${icon('sound')} 播放 / 重播</button><p>先在心里说出中文含义。拼写和中文释义暂不显示。</p><p class="fine">${q.cue==='audio'?'多义词请在下一页核对本次考查的词义；不匹配可改为不认识。':'英文解释与例句都是提示，因此对应较短复习间隔。'}</p><button class="text-button" data-action="review-text">音频不可用，改用文字辅助</button>`:`<div class="bare-word">${esc(w.word)}</div>${q.cue==='sentence'&&ex?`<p class="example-sentence">${highlightWord(ex.en,w.id)}</p>`:''}<p class="fine">${!ex||!se.definition?'此词暂缺完整语境材料，已跳过缺失音频提示。':'已记录文字辅助，不计作听音认识。'}</p>`}<div class="answer-buttons"><button data-action="review-no">${q.cue==='sentence'?'仍不认识':'想不起来，下一步提示'}</button><button class="primary" data-action="review-yes" ${listening&&!q.cuePlayed?'disabled':''}>${listening?'听懂，能说出意思':'认识，能说出意思'}</button></div><p class="fine">答完后核对释义；使用的提示越多，下次复习越早。</p>${!listening?`<button class="text-button" data-action="exclude-known" data-id="${esc(w.id)}">此词早已熟知，不再复习</button>`:''}</section>`;
}
function relationCards(w){return `<div class="relation-grid">${w.notes.map(n=>`<article class="relation-card"><span class="relation-type ${n.type==='形近词'?'shape':['词族','同词族'].includes(n.type)?'family':'meaning'}">${esc(n.type)}</span> <strong>${esc(n.word)}</strong><p>${esc(n.meaning)}</p><p class="fine">区别对比：${esc(n.difference)}</p></article>`).join('')}</div>`;}
function showKnownWords(){const ids=Object.keys(state.knownWords||{});dialog({title:'已熟知词 · 不进入复习队列',body:`<p>这是主动排除标记，不是自动判定永久掌握。可随时恢复，恢复后将重新安排复习。</p>${ids.length?ids.map(id=>`<p><strong>${esc(wordMap[id].word)}</strong> <button data-action="restore-known" data-id="${esc(id)}">恢复复习</button></p>`).join(''):'<p class="muted">还没有标记的单词。</p>'}`});}
